herbsWithin.example:
const { Gathering } = kcds.world;

const nearby = Gathering.herbsWithin(player.position, 25, player.dimension);
kcds.core.Chat.sendToPlayer(player, `${nearby.length} herbs within 25 m`);

clearHerbs.example:
const clearing = new kcds.math.Vector3(2350, 1980, 98.7);
const removed = kcds.world.Gathering.clearHerbs(clearing, 15);
console.info(`${removed} herbs removed`);

clearHerbs.exampleCs:
var clearing = new Vector3(2350, 1980, 98.7);
var removed = Gathering.ClearHerbs(clearing, 15);
Log.Info($"{removed} herbs removed");

setNaturalSpawns.example:
const { Gathering } = kcds.world;

Gathering.setNaturalSpawns(false); // no wild herbs
Gathering.setNaturalSpawns(true, 'Kopriva'); // only nettles again
